// content is never placed in the system prompt — only this framing.
func agentMemorySystemFragment(enabled, sessionUp bool) string {
	switch {
	case !enabled:
		return ""
	case !sessionUp:
		return golemAgentMemoryDegradedFragment
	default:
		return golemAgentMemoryFragment
	}
